<http://example.org/BedouinBoy> rdf:type foaf:Person, ns3:E21_Person ;
    ns3:P1_is_identified_by <http://example.org/BedouinBoyName> ;
    ns3:P129i_is_subject_of <http://example.org/BoyRecordingDescription> .

<http://example.org/BedouinBoyName> rdf:type ns3:E41_Appellation ;
    rdfs:label "Bedouin boy" .

<http://example.org/BoyRecordingDescription> rdf:type ns3:E89_Propositional_Object ;
    schema:description "A treble voice clear as a bell casually singing a melody as if the boy just walked past us. His voice penetrates layer by layer through the centuries of old acoustic patina which settled over the wax cylinder recordings. Granular noise, the delicately melting rusting that gently crackles and densifies in waves until the song of the boy nearly disappears into it. The melody shimmers through the billows of noise—comes and goes and soars on powerfully and finally terminates abruptly in the middle of the phrase at the physical end of the cylinder." .

<http://example.org/HansHelfritz> rdf:type foaf:Person, ns3:E21_Person ;
    ns3:P1_is_identified_by <http://example.org/HelfritzName> ;
    ns2:fieldOfWork <http://example.org/TravelBookAuthorField>, <http://example.org/FilmmakerField>, <http://example.org/ExplorerField>, <http://example.org/ComposerField> ;
    ns3:P14i_performed <http://example.org/HelfritzRecordings>, <http://example.org/TravelToShabwa> ;
    schema:specialty <http://example.org/CompositionStudy>, <http://example.org/ComparativeMusicologyStudy> .

<http://example.org/HelfritzName> rdf:type ns3:E41_Appellation ;
    rdfs:label "Hans Helfritz" .

<http://example.org/TravelBookAuthorField> rdf:type ns2:CACAO_0000028 ;
    rdfs:label "Travel book author" .

<http://example.org/FilmmakerField> rdf:type ns2:CACAO_0000028 ;
    rdfs:label "Filmmaker" .

<http://example.org/ExplorerField> rdf:type ns2:CACAO_0000028 ;
    rdfs:label "Explorer" .

<http://example.org/ComposerField> rdf:type ns2:CACAO_0000028 ;
    rdfs:label "Composer" .

