    rdfs:label "Helfritz's recordings" ;
    ns3:P12_occurred_in_the_presence_of <http://example.org/WaxCylinders> ;
    ns3:P129_is_about <http://example.org/BedouinBoy> .

<http://example.org/TravelToShabwa> rdf:type ns3:E7_Activity ;
    rdfs:label "Travel to Shabwa by Hans Helfritz" ;
    ns3:P7_took_place_at <http://example.org/Shabwa> ;
    ns3:P129_is_about <http://example.org/HelfritzSensations> .

<http://example.org/Shabwa> rdf:type schema:Place, ns3:E53_Place ;
    rdfs:label "Shabwa" ;
    ns3:P129i_is_subject_of <http://example.org/ShabwaLegendaryCityDescription> .

<http://example.org/ShabwaLegendaryCityDescription> rdf:type ns3:E89_Propositional_Object ;
    schema:description "legendary desert city of Shabwa" .

<http://example.org/HelfritzSensations> rdf:type ns3:E89_Propositional_Object ;
    schema:description "sensation that would bring him to momentous worldwide fame" .

<http://example.org/CompositionStudy> rdf:type schema:Specialty ;
    rdfs:label "composition with Hindemith" .

<http://example.org/ComparativeMusicologyStudy> rdf:type schema:Specialty ;
    rdfs:label "comparative musicology under Hornbostel" .

<http://example.org/EdisonPhonograph> rdf:type ns2:CACAO_0000025, ns3:E24_Physical_Human-Made_Thing ;
    rdfs:label "Edison phonograph" .

<http://example.org/WaxCylinders> rdf:type ns3:E19_Physical_Object ;
    rdfs:label "wax cylinders" ;
    ns3:P45_consists_of <http://example.org/WaxMaterial> ;
    ns3:P129i_is_subject_of <http://example.org/WaxCylindersDescription> .

<http://example.org/WaxMaterial> rdf:type ns3:E57_Material ;
    rdfs:label "wax" .

<http://example.org/WaxCylindersDescription> rdf:type ns3:E89_Propositional_Object ;
    schema:description "The musical content interested us as well as the quality of the static noise. A hundred years of turbulent history have left their audible traces in the soft wax of the cylinders." .

<http://example.org/PhonogrammArchivBerlin> rdf:type foaf:Organization, ns3:E74_Group, ns2:CACAO_0000020 ;
    rdfs:label "Phonogramm-Archiv in Berlin" ;
    ns3:P129i_is_subject_of <http://example.org/PhonogrammArchivDescription> .

<http://example.org/PhonogrammArchivDescription> rdf:type ns3:E89_Propositional_Object ;
    schema:description "The Berlin Phonogramm-Archiv is home to not only one of the most significant ethnomusicological collections in the world, it conserves in its basement what is known to be the largest acoustic archive which has documented the noise of time." .

<http://example.org/HelfritzCollection> rdf:type skos:Collection, ns3:E78_Curated_Holding ;
    rdfs:label "Collection of Helfritz" ;
    ns3:P129i_is_subject_of <http://example.org/HelfritzCollectionDescription> ;
    ns3:P109i_is_current_or_former_curator_of <http://example.org/PhonogrammArchivBerlin> .

<http://example.org/HelfritzCollectionDescription> rdf:type ns3:E89_Propositional_Object ;
    schema:description "One can hear from the collection of Helfritz that a musician was at work. His recordings reveal a keen sense for charismatic voices and interesting melodies." .

