    ns3:P129i_is_subject_of <http://example.org/RadioFeatureDescription> ;
    ns2:hasEconomicRelevance <http://example.org/PrixMarulicAward> .

<http://example.org/RadioFeatureDescription> rdf:type ns3:E89_Propositional_Object ;
    schema:description "A composition of rolling sounds was interwoven" .

<http://example.org/PrixMarulicAward> rdf:type ns2:CACAO_0000082 ;
    rdfs:label "Prix Marulic" ;
    dcterms:date "2011" .

<http://example.org/ConcertProgram> rdf:type schema:CreativeWork, ns1:CreativeWork ;
    rdfs:label "concert program" ;
    dcterms:created <http://example.org/FromRadiophonicComposition> ;
    ns3:P129i_is_subject_of <http://example.org/ConcertProgramPerformances> .

<http://example.org/FromRadiophonicComposition> rdf:type ns3:E65_Creation ;
