    ns3:P129i_is_subject_of <http://example.org/CDCompositionDescription> .

<http://example.org/CDCompositionDescription> rdf:type ns3:E89_Propositional_Object ;
    schema:description "Through its various metamorphoses and passages of time, this composition has now been documented on a CD which was released in the winter of 2013 on GRUENREKORDER and finally gives evidence to our artistic work with the historical wax cylinders of the Berlin Phonogramm-Archiv." .

<http://example.org/GRUENREKORDER> rdf:type foaf:Organization, ns3:E74_Group ;
    rdfs:label "GRUENREKORDER" .

<http://example.org/ArtistWork> rdf:type ns3:E7_Activity ;
    rdfs:label "Artistic work with historical wax cylinders" ;
    ns3:P14_carried_out_by <http://example.org/EvaPoepplein>, <http://example.org/NarratorAsActor> ;
    ns3:P12_occurred_in_the_presence_of <http://example.org/WaxCylinders> ;
    ns3:P129_is_about <http://example.org/CDComposition> .

<http://example.org/AcousticBridgeWork> rdf:type ns3:E7_Activity ;
    rdfs:label "Acoustic bridge with music into the 21st century" ;
    ns3:P14_carried_out_by <http://example.org/EvaPoepplein>, <http://example.org/NarratorAsActor> .

<http://example.org/UnidentifiedSingers> rdf:type foaf:Group, ns3:E74_Group ;
    rdfs:label "unidentified singers (men, women, and children)" ;
    ns3:P129i_is_subject_of <http://example.org/UnidentifiedSingersDescription> .

<http://example.org/UnidentifiedSingersDescription> rdf:type ns3:E89_Propositional_Object ;
    schema:description "Our special thanks go to the women, men and children whose names we do not know but whose voices we can listen to in the historical wax cylinders of the Berlin Phonogramm-Archiv. It is a privilege to have been able to work with their music." .
